-- +goose StatementBegin
INSERT INTO core.supplement_page (supplement_id, pdf_page, source_file, raw_text, sha256, needs_review) VALUES ((SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 145, 'sections/12_ameacas_paranormais.md', '', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', false);
