INSERT INTO core.ability_definition (rpg_system_id, name, slug, ability_type, description, is_active, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), 'Leitura Fria', 'poder-especialista-leitura-fria', 'CLASS_POWER', 'b Leitura Fria. Você estudou técnicas de “leitura
fria”, a capacidade de analisar e compreender uma
pessoa através de suas mais sutis reações. Uma
vez em cada interlúdio, se passar alguns minutos
interagindo com uma pessoa, ou mesmo observando-a no mesmo ambiente, você pode fazer três
perguntas pessoais sobre ela, tais como “Qual seu
filme favorito?”, “Qual sua profissão?” “Tem algum
animal de estimação?”. O mestre pode responder
com a verdade ou se negar a responder, mas, para
cada pergunta não respondida, você recebe 2
PE temporários que duram até o fim da missão.
Esse poder só pode ser usado uma vez em cada
pessoa, e apenas em NPCs. Pré-requisito: treinado
em Intuição.', false, 'Sobrevivendo ao Horror, PDF p. 23', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 23, 23);
-- +goose StatementEnd
-- +goose StatementBegin
INSERT INTO ordem.supplement_ability_detail (ability_id, supplement_id, source_page, prerequisite_text, element_id, affinity_effect, effect_text) VALUES ((SELECT id FROM core.ability_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'poder-especialista-leitura-fria'), (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 23, 'treinado', NULL, NULL, 'b Leitura Fria. Você estudou técnicas de “leitura
fria”, a capacidade de analisar e compreender uma
pessoa através de suas mais sutis reações. Uma
vez em cada interlúdio, se passar alguns minutos
interagindo com uma pessoa, ou mesmo observando-a no mesmo ambiente, você pode fazer três
perguntas pessoais sobre ela, tais como “Qual seu
filme favorito?”, “Qual sua profissão?” “Tem algum
animal de estimação?”. O mestre pode responder
com a verdade ou se negar a responder, mas, para
cada pergunta não respondida, você recebe 2
PE temporários que duram até o fim da missão.
Esse poder só pode ser usado uma vez em cada
pessoa, e apenas em NPCs. Pré-requisito: treinado
em Intuição.');
-- +goose StatementEnd
-- +goose StatementBegin
INSERT INTO core.class_ability_unlock (class_id, ability_id, required_progression, rpg_system_id) VALUES ((SELECT id FROM core.class_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'especialista'), (SELECT id FROM core.ability_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'poder-especialista-leitura-fria'), 15, (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'));
