INSERT INTO core.class_ability_unlock (class_id, ability_id, required_progression, rpg_system_id) VALUES ((SELECT id FROM core.class_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'ocultista'), (SELECT id FROM core.ability_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'poder-ocultista-tracado-conjuratorio'), 15, (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'));
