INSERT INTO core.ability_definition (rpg_system_id, name, slug, ability_type, description, is_active, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), 'Atacar das Sombras', 'trilha-cacador-65-atacar-das-sombras', 'TRAIL_ABILITY', 'NEX 65% - Atacar das Sombras. Você aprende a
usar as sombras contra o Paranormal. Você não sofre
a penalidade de –O em testes de Furtividade por
se mover ao seu deslocamento normal e, se estiver
usando uma arma que não faça barulho (como uma
faca ou um arco), a penalidade que você sofre em
Furtividade por atacar na mesma rodada é reduzida
para –O. Além disso, sua visibilidade inicial em cenas
de furtividade (veja p. 92) é sempre 1 ponto abaixo
da inicial (podendo ser negativa).', false, 'Sobrevivendo ao Horror, PDF p. 18', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 18, 18);
