INSERT INTO core.archetype_ability_unlock (archetype_id, ability_id, required_progression, rpg_system_id) VALUES ((SELECT id FROM core.archetype_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'possuido'), (SELECT id FROM core.ability_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'trilha-possuido-99-tornamo-nos-um'), 99, (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'));
