INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'arma'), 'Pregador pneumático', 'pregador-pneumatico', 'Pregador Pneumático. Outra ferramenta que
