INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'acessorio'), 'Manual operacional', 'manual-operacional', 'Manual Operacional. Um livro com lições práticas sobre um assunto. Existe um manual operacional
para cada perícia; gastar uma ação de interlúdio lendo
