INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'explosivo'), 'Dinamite', 'dinamite', 'Dinamite. Dinamite é um artefato explosivo à base
de nitroglicerina, ajeitado em um bastão com 20 cm de
comprimento. Com a mesma ação padrão é possível
acender seu pavio com uma das mãos e arremessá-la
com a outra em um ponto à sua escolha em alcance
médio. A dinamite afeta um raio de 6m a partir do
ponto de impacto; seres e objetos soltos na área sofrem
4d6 pontos de dano de impacto e 4d6 pontos de dano
de fogo e ficam em chamas (Reflexos DT Agi reduz
à metade e evita condição em chamas).', 'Sobrevivendo ao Horror, PDF p. 41', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 41);
