INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'explosivo'), 'Granada de PEM', 'granada-de-pem', 'Granada de PEM. Esta granada emite um poderoso
pulso eletromagnético que desativa todos os equipamentos elétricos em um raio de 18m até o fim da
cena. Criaturas de Energia na área sofrem 6d6 pontos
de dano de impacto e ficam atordoadas por 1 rodada
(apenas uma vez por cena, Fortitude DT Agi reduz à
metade e evita a condição).', 'Sobrevivendo ao Horror, PDF p. 41', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 41);
