INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-operacional'), 'Alarme de movimento', 'alarme-de-movimento', 'Alarme de Movimento. Este pequeno objeto de
fácil aquisição pode ser controlado por um dispositivo móvel específico ou um aplicativo de celular.
Você pode gastar uma ação completa para posicionar e ativar o alarme; após isso, sempre que houver
movimento significativo em um cone de 30m para
onde ele foi apontado, ele irá sinalizar o dispositivo
de controle. Ao acionar o alarme você pode regular
sua sensibilidade ao movimento (como padrão, ele é
acionado sempre que um ser Pequeno ou maior se
move na área). A sinalização pode ser discreta, apenas
no dispositivo, ou barulhenta, acionando um alarme
sonoro alto e agudo.', 'Sobrevivendo ao Horror, PDF p. 41', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 41);
