INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-operacional'), 'Coldre saque rápido', 'coldre-saque-rapido', 'Coldre Saque Rápido. Este coldre é projetado
para que a arma possa ser sacada ou armazenada
com um movimento mínimo. Uma vez por rodada,
você pode sacar ou guardar uma arma de fogo leve
como uma ação livre.', 'Sobrevivendo ao Horror, PDF p. 41', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 41);
