INSERT INTO ordem.supplement_item_detail (item_id, supplement_id, source_page, exact_spaces, printed_category, ammunition_capacity, item_group, special_rule) VALUES ((SELECT id FROM core.item_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'ligacao-direta-infernal'), (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 1, 'II', NULL, 'item-paranormal', NULL);
-- +goose StatementEnd
-- +goose StatementBegin
INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-paranormal'), 'Medidor de Condição Vertebral', 'medidor-de-condicao-vertebral', 'Medidor de Condição Vertebral. Este item
grotesco é uma coluna vertebral sustentada por Lodo
de Morte e revestida com cabos e fios de Energia.
Para ser usado, deve ser conectado à coluna vertebral,
em um procedimento que exige uma ação completa
e causa profunda dor e agonia, deixando o usuário
atordoado por uma rodada. O medidor conta como
uma vestimenta que fornece +2 em Fortitude. Além
disso, uma vez conectado ele se ilumina em cores que
vão do vermelho, na base, passando por amarelo no
centro até verde no topo. Essas cores indicam a saúde
do usuário, sendo verde a melhor condição. Além
disso, se o usuário estiver sob um efeito paranormal,', 'Sobrevivendo ao Horror, PDF p. 41', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 41);
-- +goose StatementEnd
-- +goose StatementBegin
