-- +goose StatementEnd
-- +goose StatementBegin
INSERT INTO ordem.supplement_item_detail (item_id, supplement_id, source_page, exact_spaces, printed_category, ammunition_capacity, item_group, special_rule) VALUES ((SELECT id FROM core.item_definition WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'medidor-de-condicao-vertebral'), (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 41, 1, 'II', NULL, 'item-paranormal', NULL);
-- +goose StatementEnd
