INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-amaldicoado-especial'), 'Espelho Refletor', 'espelho-refletor', 'Espelho Refletor. Esta pequena placa metálica foi
adquirida de corpos de criaturas como o Ciborgue, e
polida ritualisticamente até se tornar reflexiva. Um
espelho refletor pode ser usado para refletir imagens
em ângulos impossíveis; você pode gastar uma ação
de movimento para observar um ponto ou ser fora de
seu ângulo de visão em alcance médio; quando faz isso
você recebe +O em Percepção e tem uma chance de
enxergar mesmo objetos e seres com cobertura total.
Além disso, quando sofre dano de Energia, você pode
sacrificar o espelho para evitar esse dano e refleti-lo
de volta à sua origem.', 'Sobrevivendo ao Horror, PDF p. 59', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 59, 59);
