INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-amaldicoado-especial'), 'Injeção de Lodo', 'injecao-de-lodo', 'Injeção de Lodo. Uma velha seringa de bronze
enferrujado com uma grande agulha preenchida
com o Lodo preto da Morte, que escorre sutilmente
para fora. Você pode gastar uma ação padrão e o
conteúdo da seringa para injetar o Lodo em você ou
um ser adjacente voluntário. Até o fim da cena o ser
recebe vulnerabilidade a dano balístico e de Energia
mas, na próxima vez em que for reduzido a 0 PV
nesta mesma cena, em vez disso é reduzido a 1 PV.', 'Sobrevivendo ao Horror, PDF p. 59', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 59, 59);
-- +goose StatementEnd
-- +goose StatementBegin
