INSERT INTO core.item_definition (rpg_system_id, item_type_id, name, slug, description, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ((SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal'), (SELECT id FROM core.item_type WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'item-amaldicoado-especial'), 'Repositório do Fracasso', 'repositorio-do-fracasso', 'Repositório do Fracasso. Esta pequena caixinha
de madeira se assemelha a um antigo porta-joias. Seu
exterior, entretanto, é decorado com figuras espectrais que expressam um desespero profundo. Sempre
que uma criatura Paranormal em alcance médio faz
um teste, para cada resultado 1 nos d20 desse teste, o repositório do fracasso recebe uma carga, até
um máximo de 6 cargas. Uma vez por rodada, você
pode consumir uma dessas cargas para recuperar
1d4 PE. Sempre que faz isso, entretanto, você sofre
uma penalidade cumulativa de –1 em Vontade até
seu próximo interlúdio.', 'Sobrevivendo ao Horror, PDF p. 59', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 59, 59);
