INSERT INTO ordem.item_modification (name, slug, applies_to, category_increase, effect_summary, source_ref, supplement_id, supplement_page_start, supplement_page_end) VALUES ('Carregador Rápido', 'carregador-rapido-sah', 'FIREARM', 1, 'Carregador Rápido. Modificação para armas
de fogo, bestas e balestras. Em uma arma
de fogo, permite recarregá-la como uma ação
livre uma vez por rodada. Para bestas ou
balestras, permite até cinco recargas como ação
livre exigindo apenas uma mão. Após isso, é
necessário recarregar o carregador um virote de
cada vez (uma ação de movimento por virote).', 'Sobrevivendo ao Horror, PDF p. 39', (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 39, 39);
