INSERT INTO ordem.supplement_survivor_trail (class_id, supplement_id, source_page, slug, name) VALUES ((SELECT id FROM ordem.supplement_survivor_class WHERE supplement_id = (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror') AND slug = 'sobrevivente'), (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror'), 33, 'esperto', 'Esperto');
