INSERT INTO ordem.threat_element (threat_id, element_id, is_primary, sort_order, source_ref) VALUES ((SELECT c.id FROM core.rpg_character c WHERE c.supplement_id = (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror') AND c.name = 'Melancolia'), (SELECT id FROM ordem.element WHERE slug = 'sangue'), false, 1, 'Sobrevivendo ao Horror, PDF p. 140');
