INSERT INTO ordem.threat_action (threat_id, name, action_type, description, sort_order, source_ref) VALUES ((SELECT c.id FROM core.rpg_character c WHERE c.supplement_id = (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror') AND c.name = 'Quibungo'), 'INSTINTOS BESTIAIS', 'REAÇÃO', 'REAÇÃO  INSTINTOS BESTIAIS
Uma vez por rodada, o Quibungo pode se
esquivar completamente de um ataque à
distância ou de um efeito em área, evitando
completamente seu dano.', 3, 'Sobrevivendo ao Horror, PDF p. 143-144');
