INSERT INTO ordem.threat (character_id, being_type_id, challenge_value, slug, source_ref, defense, hit_points, wounded_at, agility, strength, intellect, presence, vigor, statblock_data) VALUES ((SELECT c.id FROM core.rpg_character c WHERE c.supplement_id = (SELECT id FROM core.rpg_supplement WHERE rpg_system_id = (SELECT id FROM core.rpg_system WHERE slug = 'ordem-paranormal') AND slug = 'sobrevivendo-ao-horror') AND c.name = 'Cavalo'), (SELECT id FROM ordem.being_type WHERE slug = 'animal'), 10, 'cavalo', 'Sobrevivendo ao Horror, PDF p. 164', 13, 12, 6, 1, 3, 0, 1, 2, '{"source_text": "CAVALO VD 10\nMesmo nos dias de hoje, cavalos são empregados em\ndiversas situações. Na cidade, podem ser usados por\nforças policiais ou como animais de esportes e recreação. No campo, servem como meio de transporte e\ntração. Embora geralmente pacatos, são capazes de\ndesferir chutes poderosos com seus cascos.\nANIMAL  GRANDE\nSENTIDOS Percepção O+5 | Iniciativa O+5\nFARO, VISÃO NA PENUMBRA\nDEFESA 13\nFortitude 2O | Reflexos O+5 | Vontade O\nPONTOS DE VIDA 12 | Machucado 6\nDESLOCAMENTO 15m | 10\nAGI 1 FOR 3 INT 0 PRE 1 VIG 2\nMONTARIA Um personagem treinado em Adestramento pode usar um cavalo como montaria. Ele conta\ncomo um aliado que aumenta seu deslocamento para\n15 e fornece uma ação extra por rodada (apenas para\nse deslocar).\nAÇÕES\nPADRÃO  AGREDIR\nCASCOS Corpo a corpo\nTeste O+5 | Dano 2d4+3 impacto", "source_page_start": 164, "source_page_end": 164, "review_required": true}'::jsonb);
