IF NOT ((SELECT count(*) FROM core.supplement_page WHERE supplement_id = sid AND sha256 <> encode(digest(convert_to(raw_text, 'UTF8'), 'sha256'), 'hex')) = 0) THEN RAISE EXCEPTION 'SAH integrity: source hashes'; END IF;
IF NOT ((SELECT count(*) FROM core.origin_definition WHERE supplement_id = sid) = 20) THEN RAISE EXCEPTION 'SAH integrity: origins'; END IF;
