IF NOT ((SELECT count(*) FROM core.ability_definition WHERE supplement_id = sid AND ability_type = 'PARANORMAL_POWER') = 8) THEN RAISE EXCEPTION 'SAH integrity: paranormal powers'; END IF;
IF NOT ((SELECT count(*) FROM core.ability_definition WHERE supplement_id = sid AND ability_type = 'RITUAL') = 16) THEN RAISE EXCEPTION 'SAH integrity: rituals'; END IF;
IF NOT ((SELECT count(*) FROM core.item_definition i JOIN ordem.weapon w ON w.item_id = i.id WHERE i.supplement_id = sid) = 11) THEN RAISE EXCEPTION 'SAH integrity: weapons'; END IF;
IF NOT ((SELECT count(*) FROM core.item_definition WHERE supplement_id = sid) = 75) THEN RAISE EXCEPTION 'SAH integrity: equipment'; END IF;
IF NOT ((SELECT count(*) FROM core.item_definition i JOIN ordem.special_cursed_item c ON c.item_id = i.id WHERE i.supplement_id = sid) = 19) THEN RAISE EXCEPTION 'SAH integrity: cursed items'; END IF;
IF NOT ((SELECT count(*) FROM ordem.item_modification WHERE supplement_id = sid) = 3) THEN RAISE EXCEPTION 'SAH integrity: item modifications'; END IF;
IF NOT ((SELECT count(*) FROM core.rpg_character WHERE supplement_id = sid AND character_type = 'THREAT') = 28) THEN RAISE EXCEPTION 'SAH integrity: fixed threats'; END IF;
IF NOT ((SELECT count(*) FROM ordem.threat t JOIN core.rpg_character c ON c.id = t.character_id WHERE c.supplement_id = sid AND (t.defense IS NULL OR t.hit_points IS NULL)) = 0) THEN RAISE EXCEPTION 'SAH integrity: fixed threat statblocks'; END IF;
IF NOT ((SELECT t.hit_points FROM ordem.threat t JOIN core.rpg_character c ON c.id = t.character_id WHERE c.supplement_id = sid AND t.slug = 'amigo-imaginario') = 1000) THEN RAISE EXCEPTION 'SAH integrity: thousand-point threat'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_survivor_stage WHERE supplement_id = sid) = 5) THEN RAISE EXCEPTION 'SAH integrity: survivor stages'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_survivor_trail WHERE supplement_id = sid) = 3) THEN RAISE EXCEPTION 'SAH integrity: survivor trails'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_rule WHERE supplement_id = sid AND parent_id IS NULL AND source_page_start BETWEEN 82 AND 124) = 4) THEN RAISE EXCEPTION 'SAH integrity: rule families'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_rule WHERE supplement_id = sid AND parent_id IS NULL AND source_page_start < 82) = 1) THEN RAISE EXCEPTION 'SAH integrity: equipment options'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_threat_template WHERE supplement_id = sid) = 1) THEN RAISE EXCEPTION 'SAH integrity: threat templates'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_threat_example WHERE supplement_id = sid) = 1) THEN RAISE EXCEPTION 'SAH integrity: threat example'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_ritual_version WHERE supplement_id = sid) = 45) THEN RAISE EXCEPTION 'SAH integrity: ritual versions'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_item_detail WHERE supplement_id = sid AND exact_spaces <> trunc(exact_spaces)) = 18) THEN RAISE EXCEPTION 'SAH integrity: fractional spaces'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_item_detail d JOIN ordem.item_rule r ON r.item_id = d.item_id WHERE d.supplement_id = sid AND d.exact_spaces <> trunc(d.exact_spaces) AND r.spaces IS NOT NULL) = 0) THEN RAISE EXCEPTION 'SAH integrity: fractional legacy spaces'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_item_alias WHERE supplement_id = sid) = 1) THEN RAISE EXCEPTION 'SAH integrity: canonical item alias'; END IF;
IF NOT ((SELECT count(*) FROM ordem.supplement_ability_classification WHERE supplement_id = sid) = 4) THEN RAISE EXCEPTION 'SAH integrity: base power classifications'; END IF;
END $$;
